(async () => {
const fs = await import('node:fs');
const lineas = fs.readFileSync(String.raw`{{ $json.file_path }}`, 'utf8').trim().split(/\r?\n/);
const vistas = new Set([lineas[0]]);
const salida = [lineas[0]];
for (const linea of lineas.slice(1)) {
  const limpia = linea.trim();
  if (!limpia || vistas.has(limpia)) continue;
  vistas.add(limpia);
  salida.push(limpia);
}
console.log(JSON.stringify({ texto: salida.join(String.fromCharCode(10)), filas: salida.length }));
})();

(async () => {
const fs = await import('node:fs');
const objetos = JSON.parse(fs.readFileSync(String.raw`{{ $json.file_path }}`, 'utf8'));
const lista = Array.isArray(objetos) ? objetos : [objetos];
const cabecera = Object.keys(lista[0] || {});
const filas = lista.map((o) => cabecera.map((c) => String(o[c] === undefined ? '' : o[c])));
console.log(JSON.stringify({ cabecera: cabecera, filas: filas }));
})();

(async () => {
const fs = await import('node:fs');
const lineas = fs.readFileSync(String.raw`{{ $json.file_path }}`, 'utf8').trim().split(/\r?\n/);
const cabecera = lineas[0].split(',');
const objetos = lineas.slice(1).map((l) => {
  const celdas = l.split(',');
  const obj = {};
  cabecera.forEach((c, i) => { obj[c] = celdas[i] === undefined ? '' : celdas[i]; });
  return obj;
});
console.log(JSON.stringify({ texto: JSON.stringify(objetos, null, 2), filas: objetos.length }));
})();

